A singly linked list holds 10, 20, 30, 40, 50, 60, 70, 80. What does it hold from the head after `f(head)`?

```c
struct node *f(struct node *h) {
    if (h == NULL) return h;
    struct node *o = h, *e = h->next, *eh = e;
    while (e != NULL && e->next != NULL) {
        o->next = e->next;
        o = o->next;
        e->next = o->next;
        e = e->next;
    }
    o->next = eh;
    return h;
}
```
